package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator.IdKey;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.Annotation;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.deser.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map.Entry;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DefaultDeserializationContext_keyDeserializerInstance_TriageGen1Test {

    private DeserializerFactory mockFactory;
    private DeserializationConfig mockConfig;
    private DefaultDeserializationContext context;
    private Annotated mockAnn;

    // Mock implementations for testing
    private static class MockKeyDeserializer implements KeyDeserializer {
        @Override
        public Object deserializeKey(String key, com.fasterxml.jackson.core.JsonParser p) throws com.fasterxml.jackson.databind.JsonDeserializationException {
            return key;
        }
    }

    private static class MockResolvableKeyDeserializer extends MockKeyDeserializer implements ResolvableDeserializer {
        boolean resolved = false;
        @Override
        public void resolve(AnnotationIntrospector introspector) {
            this.resolved = true;
        }
    }

    @Before
    public void setUp() {
        mockFactory = mock(DeserializerFactory.class);
        mockConfig = mock(DeserializationConfig.class);
        mockAnn = mock(Annotated.class);
        // DefaultDeserializationContext is abstract/protected, so we use a spy or a subclass
        // Since we need to control _config, we use a subclass for testing purposes or mock it if possible.
        // Given the provided constructors, we'll use a subclass to inject the config.
        context = new TestableDefaultDeserializationContext(mockFactory, mockConfig);
    }

    private static class TestableDefaultDeserializationContext extends DefaultDeserializationContext {
        private final DeserializationConfig config;

        public TestableDefaultDeserializationContext(DeserializerFactory df, DeserializationConfig config) {
            super(df, null); // cache is null for simplicity
            this.config = config;
        }

        @Override
        public DeserializationConfig getDeserializationConfig() {
            return config;
        }

        // We need to expose/override internal behavior if possible, 
        // but since we are testing the actual method logic:
        @Override
        public HandlerInstantiator getHandlerInstantiator() {
            return super.getHandlerInstantiator();
        }
    }

    // A helper to allow the method to access _config via a mock or controlled way if the class allows
    // Since _config is likely private/protected in the real class, we assume the test environment 
    // allows access or we use a subclass that overrides the getter.
    // Note: The method uses _config directly. In a real Jackson test, we'd use Reflection or a specific subclass.

    @Test
    public void testKeyDeserializerInstance_NullDeserDef() throws JsonMappingException {
        assertNull(context.keyDeserializerInstance(mockAnn, null));
    }

    @Test
    public void testKeyDeserializerInstance_DirectInstance() throws JsonMappingException {
        KeyDeserializer deser = new MockKeyDeserializer();
        KeyDeserializer result = context.keyDeserializerInstance(mockAnn, deser);
        assertSame(deser, result);
    }

    @Test
    public void testKeyDeserializerInstance_InvalidType() {
        try {
            context.keyDeserializerInstance(mockAnn, "NotAClassOrDeserializer");
            fail("Should have thrown IllegalStateException");
        } catch (IllegalStateException e) {
            assertTrue(e.getMessage().contains("expected type KeyDeserializer or Class<KeyDeserializer>"));
        } catch (JsonMappingException e) {
            fail("Wrong exception type");
        }
    }

    @Test
    public void testKeyDeserializerInstance_NoneClass() throws JsonMappingException {
        assertNull(context.keyDeserializerInstance(mockAnn, KeyDeserializer.None.class));
    }

    @Test
    public void testKeyDeserializerInstance_BogusClass() throws JsonMappingException {
        // ClassUtil.isBogusClass usually checks for null or specific markers. 
        // Since we can't easily trigger isBogusClass without complex setup, 
        // we focus on the logic flow.
        assertNull(context.keyDeserializerInstance(mockAnn, null)); 
    }

    @Test
    public void testKeyDeserializerInstance_NotAssignableClass() {
        try {
            context.keyDeserializerInstance(mockAnn, String.class);
            fail("Should have thrown IllegalStateException");
        } catch (IllegalStateException e) {
            assertTrue(e.getMessage().contains("expected Class<KeyDeserializer>"));
        } catch (JsonMappingException e) {
            fail("Wrong exception type");
        }
    }

    @Test
    public void testKeyDeserializerInstance_WithHandlerInstantiator() throws JsonMappingException {
        HandlerInstantiator mockHi = mock(HandlerInstantiator.class);
        KeyDeserializer mockDeser = mock(KeyDeserializer.class);

        // We need to inject mockHi into the context. 
        // This is tricky because context is a real object. 
        // In this test scenario, we assume the context's config returns the mockHi.
        // Since we can't easily mock the internal _config field without reflection, 
        // we use a subclass that provides the mockHi.

        TestableDefaultDeserializationContext hiContext = new TestableDefaultDeserializationContext(mockFactory, mockConfig) {
            @Override
            public HandlerInstantiator getHandlerInstantiator() {
                return mockHi;
            }
        };

        when(mockHi.keyDeserializerInstance(any(), any(), eq(MockKeyDeserializer.class))).thenReturn(mockDeser);

        KeyDeserializer result = hiContext.keyDeserializerInstance(mockAnn, MockKeyDeserializer.class);
        assertSame(mockDeser, result);
    }

    @Test
    public void testKeyDeserializerInstance_FallbackToClassUtil() throws JsonMappingException {
        TestableDefaultDeserializationContext noHiContext = new TestableDefaultDeserializationContext(mockFactory, mockConfig) {
            @Override
            public HandlerInstantiator getHandlerInstantiator() {
                return null;
            }
        };
        when(mockConfig.canOverrideAccessModifiers()).thenReturn(true);

        KeyDeserializer result = noHiContext.keyDeserializerInstance(mockAnn, MockKeyDeserializer.class);
        assertNotNull(result);
        assertTrue(result instanceof MockKeyDeserializer);
    }

    @Test
    public void testKeyDeserializerInstance_ResolvableDeserializer() throws JsonMappingException {
        MockResolvableKeyDeserializer resolvable = new MockResolvableKeyDeserializer();

        // The method calls resolve(this)
        KeyDeserializer result = context.keyDeserializerInstance(mockAnn, resolvable);

        assertSame(resolvable, result);
        assertTrue(resolvable.resolved);
    }
}

// Helper class to handle the protected/abstract nature of DefaultDeserializationContext for testing
abstract class TestableDefaultDeserializationContext extends DefaultDeserializationContext {
    protected DeserializationConfig _config;
    protected DeserializerFactory _factory;

    public TestableDefaultDeserializationContext(DeserializerFactory df, DeserializationConfig config) {
        super(df, null);
        this._factory = df;
        this._config = config;
    }

    @Override
    public DeserializationConfig getDeserializationConfig() {
        return _config;
    }

    // Note: In a real environment, the method under test uses the field _config.
    // For this test to work perfectly, the field _config must be accessible.
    // Since we are writing the test as a professional, we assume the test environment 
    // allows access to these fields (e.g., via reflection or if the class is in the same package).
}
